using System;using System.IO;using System.Collections.Generic;using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 sealed class PreparedStore:IDisposable {
  readonly object gate=new object();readonly List<long> offsets=new List<long>();readonly List<int> lengths=new List<int>();readonly List<byte[]> memory=new List<byte[]>();readonly long memoryLimit;FileStream writer,reader;readonly string path,indexPath;public long MemoryBytes,DiskBytes;public bool Complete;public double Fps;
  public int Count{get{lock(gate)return offsets.Count;}}
  public PreparedStore(string key,long limit,double fps){memoryLimit=limit;Fps=fps;path=Path.Combine(AppPaths.Data("Cache"),key+".mjpg");indexPath=path+".json";
   if(File.Exists(path)&&File.Exists(indexPath))try{var json=JObject.Parse(File.ReadAllText(indexPath));Fps=(double)json["fps"];foreach(JArray pair in (JArray)json["frames"]){offsets.Add((long)pair[0]);lengths.Add((int)pair[1]);memory.Add(null);}DiskBytes=new FileInfo(path).Length;if(offsets.Count==0||offsets[offsets.Count-1]+lengths[lengths.Count-1]>DiskBytes)throw new InvalidDataException();Complete=true;}catch{offsets.Clear();lengths.Clear();memory.Clear();Complete=false;}
   if(!Complete)writer=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.Read,65536);reader=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite,65536);
  }
  public void Add(byte[] jpeg){lock(gate){if(Complete)throw new InvalidOperationException();if(writer.Position+jpeg.Length>8L*1024*1024*1024)throw new IOException("Prepared video exceeds the 8 GB cache limit. Choose a shorter clip.");long at=writer.Position;writer.Write(jpeg,0,jpeg.Length);bool retain=MemoryBytes+jpeg.Length<=memoryLimit;offsets.Add(at);lengths.Add(jpeg.Length);memory.Add(retain?jpeg:null);if(retain)MemoryBytes+=jpeg.Length;DiskBytes=writer.Position;}}
  public byte[] Read(int index){lock(gate){if(index<0||index>=offsets.Count)return null;if(memory[index]!=null)return memory[index];if(writer!=null)writer.Flush();var bytes=new byte[lengths[index]];reader.Position=offsets[index];int done=0;while(done<bytes.Length){int count=reader.Read(bytes,done,bytes.Length-done);if(count==0)throw new EndOfStreamException("Prepared frame is incomplete.");done+=count;}if(MemoryBytes+bytes.Length<=memoryLimit){memory[index]=bytes;MemoryBytes+=bytes.Length;}return bytes;}}
  public void Finish(){lock(gate){writer.Flush(true);writer.Dispose();writer=null;var frames=new JArray();for(int i=0;i<offsets.Count;i++)frames.Add(new JArray(offsets[i],lengths[i]));AppPaths.SaveJson(indexPath,new JObject{{"fps",Fps},{"frames",frames}});Complete=true;}}
  public void Dispose(){lock(gate){if(reader!=null)reader.Dispose();if(writer!=null)writer.Dispose();memory.Clear();if(!Complete){try{File.Delete(path);}catch{}}}}
  public static void Prune(long maxBytes=8L*1024*1024*1024){var files=new DirectoryInfo(AppPaths.Data("Cache")).GetFiles("*.mjpg");long total=0;foreach(var file in files)total+=file.Length;Array.Sort(files,(a,b)=>a.LastAccessTimeUtc.CompareTo(b.LastAccessTimeUtc));foreach(var file in files){if(total<=maxBytes)break;try{long size=file.Length;file.Delete();if(File.Exists(file.FullName+".json"))File.Delete(file.FullName+".json");total-=size;}catch{}}}
 }
}
